head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거)
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
// 앞쪽에 10행 삽입(1·5번째 = depth 1, 나머지 depth 2)
scwin.trigger2_onclick = function(e) {
	for (var i = 0; i < 10; i++) {
		dataList1.insertRow();
		var data = 11111111111111 * (i + 1);
		dataList1.setRowJSON(i, {
			"col1": data,
			"col2": (i == 0 || i == 4) ? 1 : 2
		});
	}
};
scwin.fireOver = function(id) {
	var node = scwin.__getDom($p.id + id);
	var evt = document.createEvent('MouseEvents');
	evt.initEvent('mouseover', true, false);
	node.dispatchEvent(evt);
};
scwin.__checkHtml = function() {
	return scwin.__getDom($p.id + 'wq_uuid_3_tooltip').innerHTML;
};
scwin.onpageload = function() {
	dataList1.setJSON([
		{ "col1": "aaaaaaaaaaaaaaaaaaaaaaa", "col2": 1, "col3": "" },
		{ "col1": "bbbbbbbbbbbbbbbbbbbbbbb", "col2": 2, "col3": "" },
		{ "col1": "ccccccccccccccccccccccc", "col2": 2, "col3": "" },
		{ "col1": "ddddddddddddddddddddddd", "col2": 3, "col3": "" }
	], true);
};
